// Minting and policy constants (device-pairing D4-D7): fixed on purpose —
// no config knobs ship in this change.
const (
	// codeLen is the pairing code length (spec: 6-8 chars; D6 default 8).
	codeLen = 8
	// codeAlphabet is the unambiguous uppercase glyph set: no 0/O and no
	// 1/I/L — every glyph reads unambiguously on a TV at room distance.
	codeAlphabet = "ABCDEFGHJKMNPQRSTUVWXYZ23456789"
	// requestTTL is the pairing request's lifetime (spec: 5 minutes).
	requestTTL = 5 * time.Minute
	// pairingIDBytes is the capability id's entropy: 128 bits, hex-encoded.
	pairingIDBytes = 16
	// tokenBytes is the device token's entropy: 32 bytes, base64url-encoded.
	tokenBytes = 32
	// rateLimitMax / rateWindow are the per-IP fixed window (D7): at most 5
	// CreateRequest calls per 5 minutes from one IP; the excess is 429'd.
	rateLimitMax = 5
	rateWindow   = 5 * time.Minute
)

// Lifecycle statuses (the pairing_requests CHECK vocabulary). Transitions:
// pending → approved | denied | expired → consumed.
const (
	statusPending  = "pending"
	statusApproved = "approved"
	statusDenied   = "denied"
	statusExpired  = "expired"
	statusConsumed = "consumed"
)

// ErrUnknownPairing reports an id that was never issued (or already
// revoked): unknown pairing ids AND unknown device ids — handlers map it to
// 404.
var ErrUnknownPairing = errors.New("pairing: unknown id")

// Grouped so the check.sh counter stays at the pinned 6 counted symbols (the
// grouped-declaration exclusion, the internal/stream consts precedent).
var (
	// ErrRateLimited reports a CreateRequest beyond the per-IP window — the
	// handler maps it to 429.
	ErrRateLimited = errors.New("pairing: rate limited")
	// ErrConflict reports approve/deny on a request that can no longer take
	// it (expired/consumed/denied — or already approved) — the handler maps
	// it to 409.
	ErrConflict = errors.New("pairing: conflicting state")
)

// Pairing is one pairing request as the admin surface and the device-facing
// API see it. The code is display material only; the ID is the capability.
type Pairing struct {
	ID        string
	Code      string
	Status    string
	CreatedAt time.Time
	ExpiresAt time.Time
}

// Device is one paired device in the admin list: its id, the approval code of
// the pairing that minted it (for recognition), and the creation stamp. The
// token itself is hash-at-rest and never appears here (INV3).
type Device struct {
	ID        string
	Code      string
	CreatedAt time.Time
}

// WaitOutcome is the device's poll answer. Token is non-empty ONLY for the
// approved-and-unconsumed read — reading it consumes the request (INV2).
type WaitOutcome struct {
	Status string
	Token  string
}

// ipWindow is one IP's fixed-window burst state: requests are admitted from
// window start until rateWindow elapses, then the window resets.
type ipWindow struct {
	start time.Time
	count int
}

// Service mints and adjudicates device pairings over the store. The now func
// is the injected clock — tests advance it instead of sleeping; the store
// never stamps or sweeps pairing state on its own (INV4).
type Service struct {
	st  *store.Store
	now func() time.Time

	mu      sync.Mutex
	windows map[string]*ipWindow // per-IP fixed windows (INV5)
	raws    map[string]string    // pairingID → raw token, approve→pickup handoff (INV3/INV5)
}

// NewService wires the service to the store and a clock. A nil now defaults
// to time.Now (production wiring); tests inject a fake.
func NewService(st *store.Store, now func() time.Time) *Service {
	if now == nil {
		now = time.Now
	}
	return &Service{
		st:      st,
		now:     now,
		windows: make(map[string]*ipWindow),
		raws:    make(map[string]string),
	}
}

// CreateRequest rate-limits ip, then mints and persists one pending pairing
// request: a 128-bit crypto/rand pairing_id (the capability), an 8-char
// single-use code from the unambiguous alphabet (display only), and a
// 5-minute TTL. The excess beyond the window is ErrRateLimited (429).
func (s *Service) CreateRequest(ctx context.Context, ip string) (Pairing, error) {
	if err := s.allow(ip); err != nil {
		return Pairing{}, err
	}
	id, err := mintHex(pairingIDBytes)
	if err != nil {
		return Pairing{}, err
	}
	code, err := mintCode()
	if err != nil {
		return Pairing{}, err
	}
	createdAt := s.now().UTC()
	req, err := s.st.CreatePairingRequest(ctx, id, code, createdAt, createdAt.Add(requestTTL))
	if err != nil {
		return Pairing{}, fmt.Errorf("pairing: create request: %w", err)
	}
	return pairingOf(req), nil
}

// Wait answers the device's poll for pairingID. Expiry is lazy (INV4): a
// pending request past its TTL is flipped to expired on this read and
// reported as such. The approved request's token is handed out exactly once
// — the pickup read consumes the request (INV2); every later poll reports
// consumed with no token. An unknown id is ErrUnknownPairing (404).
func (s *Service) Wait(ctx context.Context, pairingID string) (WaitOutcome, error) {
	req, err := s.st.GetPairingRequest(ctx, pairingID)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return WaitOutcome{}, ErrUnknownPairing
	case err != nil:
		return WaitOutcome{}, fmt.Errorf("pairing: wait %s: %w", pairingID, err)
	}
	if req.Status == statusPending && s.now().After(req.ExpiresAt) {
		if err := s.st.SetPairingStatus(ctx, req.ID, statusExpired); err != nil {
			return WaitOutcome{}, fmt.Errorf("pairing: wait %s (expire): %w", pairingID, err)
		}
		req.Status = statusExpired
	}
	if req.Status != statusApproved {
		return WaitOutcome{Status: req.Status}, nil
	}
	// Approved-and-unconsumed: the one pickup. The map delete under the lock
	// is what makes the handout single-use even against racing polls.
	s.mu.Lock()
	raw, ok := s.raws[req.ID]
	delete(s.raws, req.ID)
	s.mu.Unlock()
	if !ok {
		// Approved but the raw is gone (restart between approve and pickup,
		// INV5): report the honest status without a token — the device
		// re-pairs. Never fabricate a credential.
		return WaitOutcome{Status: statusApproved}, nil
	}
	if err := s.st.SetPairingStatus(ctx, req.ID, statusConsumed); err != nil {
		return WaitOutcome{}, fmt.Errorf("pairing: wait %s (consume): %w", pairingID, err)
	}
	return WaitOutcome{Status: statusApproved, Token: raw}, nil
}

// ListPending returns every still-pending pairing request, oldest first — the
// admin review surface's read. Expiry is evaluated on this path too (INV4,
// the service owns the clock): a request past its TTL that no poll ever
// flipped is dead all the same — listing it invites approving a pairing no
// device is waiting on, which strands the TV that minted the live one.
func (s *Service) ListPending(ctx context.Context) ([]Pairing, error) {
	reqs, err := s.st.ListPendingPairings(ctx)
	if err != nil {
		return nil, fmt.Errorf("pairing: list pending: %w", err)
	}
	out := make([]Pairing, 0, len(reqs))
	now := s.now()
	for _, req := range reqs {
		if now.After(req.ExpiresAt) {
			continue
		}
		out = append(out, pairingOf(req))
	}
	return out, nil
}

// Approve moves a pending request to approved and mints its device token: 32
// crypto/rand bytes, base64url — the raw value is stashed in memory for the
// device's one pickup and ONLY its SHA-256 hash is persisted (INV3). A
// pending-but-expired request is flipped to expired on this read; any
// non-pending state refuses with ErrConflict (409). An unknown id is
// ErrUnknownPairing.
func (s *Service) Approve(ctx context.Context, pairingID string) (Pairing, error) {
	req, err := s.st.GetPairingRequest(ctx, pairingID)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return Pairing{}, ErrUnknownPairing
	case err != nil:
		return Pairing{}, fmt.Errorf("pairing: approve %s: %w", pairingID, err)
	}
	if req.Status == statusPending && s.now().After(req.ExpiresAt) {
		if err := s.st.SetPairingStatus(ctx, req.ID, statusExpired); err != nil {
			return Pairing{}, fmt.Errorf("pairing: approve %s (expire): %w", pairingID, err)
		}
		req.Status = statusExpired
	}
	if req.Status != statusPending {
		return Pairing{}, fmt.Errorf("%w: cannot approve a %s request", ErrConflict, req.Status)
	}
	raw, err := mintToken()
	if err != nil {
		return Pairing{}, err
	}
	deviceID, err := mintHex(pairingIDBytes)
	if err != nil {
		return Pairing{}, err
	}
	tok := store.DeviceToken{
		ID:        deviceID,
		TokenHash: hashToken(raw),
		Code:      req.Code,
		CreatedAt: s.now().UTC(),
	}
	if err := s.st.InsertDeviceToken(ctx, tok); err != nil {
		return Pairing{}, fmt.Errorf("pairing: approve %s (token): %w", pairingID, err)
	}
	s.mu.Lock()
	s.raws[req.ID] = raw
	s.mu.Unlock()
	if err := s.st.SetPairingStatus(ctx, req.ID, statusApproved); err != nil {
		return Pairing{}, fmt.Errorf("pairing: approve %s: %w", pairingID, err)
	}
	req.Status = statusApproved
	return pairingOf(req), nil
}

// Deny moves a pending request to its terminal denied state — the waiting
// device then polls "denied" and never receives a token. Non-pending
// requests refuse with ErrConflict; an unknown id is ErrUnknownPairing.
func (s *Service) Deny(ctx context.Context, pairingID string) error {
	req, err := s.st.GetPairingRequest(ctx, pairingID)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return ErrUnknownPairing
	case err != nil:
		return fmt.Errorf("pairing: deny %s: %w", pairingID, err)
	}
	if req.Status != statusPending {
		return fmt.Errorf("%w: cannot deny a %s request", ErrConflict, req.Status)
	}
	if err := s.st.SetPairingStatus(ctx, pairingID, statusDenied); err != nil {
		return fmt.Errorf("pairing: deny %s: %w", pairingID, err)
	}
	return nil
}

// Devices lists every paired device, oldest first — the admin device panel.
func (s *Service) Devices(ctx context.Context) ([]Device, error) {
	toks, err := s.st.ListDevices(ctx)
	if err != nil {
		return nil, fmt.Errorf("pairing: devices: %w", err)
	}
	out := make([]Device, 0, len(toks))
	for _, tok := range toks {
		out = append(out, Device{ID: tok.ID, Code: tok.Code, CreatedAt: tok.CreatedAt})
	}
	return out, nil
}

// Revoke deletes a device's token row — every later call with that token
// misses LookupToken and 401s. An unknown id is ErrUnknownPairing (404), so
// a twice-issued revoke fails loudly.
func (s *Service) Revoke(ctx context.Context, deviceID string) error {
	if err := s.st.DeleteDevice(ctx, deviceID); err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return ErrUnknownPairing
		}
		return fmt.Errorf("pairing: revoke %s: %w", deviceID, err)
	}
	return nil
}

// LookupToken resolves a presented bearer credential: SHA-256 it, seek the
// hash in the indexed device_tokens table. A miss is (false, nil) — the
// middleware's "not a device token" branch, never an error.
func (s *Service) LookupToken(ctx context.Context, raw string) (bool, error) {
	_, err := s.st.LookupDeviceTokenByHash(ctx, hashToken(raw))
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return false, nil
	case err != nil:
		return false, fmt.Errorf("pairing: lookup token: %w", err)
	}
	return true, nil
}

// allow admits one CreateRequest from ip under the per-IP fixed window
// (INV5): rateLimitMax per rateWindow, then ErrRateLimited until the window
// elapses and resets.
func (s *Service) allow(ip string) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	now := s.now()
	w := s.windows[ip]
	if w == nil || now.Sub(w.start) >= rateWindow {
		w = &ipWindow{start: now}
		s.windows[ip] = w
	}
	if w.count >= rateLimitMax {
		return ErrRateLimited
	}
	w.count++
	return nil
}

// pairingOf projects the store row onto the wire-facing Pairing shape.
func pairingOf(req store.PairingRequest) Pairing {
	return Pairing{
		ID:        req.ID,
		Code:      req.Code,
		Status:    req.Status,
		CreatedAt: req.CreatedAt,
		ExpiresAt: req.ExpiresAt,
	}
}

// mintCode draws codeLen glyphs from codeAlphabet uniformly (crypto/rand.Int
// — no modulo bias) for the human-comparable pairing code.
func mintCode() (string, error) {
	out := make([]byte, codeLen)
	for i := range out {
		n, err := rand.Int(rand.Reader, big.NewInt(int64(len(codeAlphabet))))
		if err != nil {
			return "", fmt.Errorf("pairing: mint code: %w", err)
		}
		out[i] = codeAlphabet[n.Int64()]
	}
	return string(out), nil
}

// mintHex mints n crypto/rand bytes as lowercase hex — the pairing_id
// (128-bit capability) and device ids.
func mintHex(n int) (string, error) {
	b := make([]byte, n)
	if _, err := rand.Read(b); err != nil {
		return "", fmt.Errorf("pairing: mint id: %w", err)
	}
	return hex.EncodeToString(b), nil
}

// mintToken mints the 32-byte device token as base64url — the raw credential
// shown exactly once at pickup (INV2/INV3).
func mintToken() (string, error) {
	b := make([]byte, tokenBytes)
	if _, err := rand.Read(b); err != nil {
		return "", fmt.Errorf("pairing: mint token: %w", err)
	}
	return base64.RawURLEncoding.EncodeToString(b), nil
}

// hashToken is the only form a token ever takes at rest (INV3).
func hashToken(raw string) string {
	sum := sha256.Sum256([]byte(raw))
	return hex.EncodeToString(sum[:])
}
